def max_triangle_area(points):
    # Group by x and y coordinates
    from collections import defaultdict

    x_dict = defaultdict(list)
    y_dict = defaultdict(list)
    n = len(points)
    max_area2 = 0  # area × 2

    # Build maps for fast lookup
    for x, y in points:
        x_dict[x].append(y)
        y_dict[y].append(x)

    used = set(tuple(pt) for pt in points)  # To check if point exists

    # Case 1: Sides parallel to x-axis (same y)
    for y, xs in y_dict.items():
        xs = sorted(xs)
        # Try all base pairs sharing y
        for i in range(len(xs)):
            for j in range(i+1, len(xs)):
                x1, x2 = xs[i], xs[j]
                base = abs(x2 - x1)
                if base == 0:
                    continue  # skip degenerate
                # For every possible third point with x = x1 or x2 but y ≠ y (height)
                for y3 in x_dict[x1]:
                    if y3 != y:
                        height = abs(y3 - y)
                        area2 = base * height  # doubled area
                        if area2 > max_area2:
                            max_area2 = area2
                for y3 in x_dict[x2]:
                    if y3 != y:
                        height = abs(y3 - y)
                        area2 = base * height
                        if area2 > max_area2:
                            max_area2 = area2

    # Case 2: Sides parallel to y-axis (same x)
    for x, ys in x_dict.items():
        ys = sorted(ys)
        for i in range(len(ys)):
            for j in range(i+1, len(ys)):
                y1, y2 = ys[i], ys[j]
                base = abs(y2 - y1)
                if base == 0:
                    continue
                # For every possible third point with y = y1 or y2 but x ≠ x (height)
                for x3 in y_dict[y1]:
                    if x3 != x:
                        height = abs(x3 - x)
                        area2 = base * height
                        if area2 > max_area2:
                            max_area2 = area2
                for x3 in y_dict[y2]:
                    if x3 != x:
                        height = abs(x3 - x)
                        area2 = base * height
                        if area2 > max_area2:
                            max_area2 = area2

    return max_area2 if max_area2 > 0 else -1
